import { createStyleContext } from "@styled-system/jsx"
import { ChevronDown } from "lucide-react"
import { Accordion as AccordionPrimitive } from "radix-ui"
import { type ComponentPropsWithoutRef, ElementRef, forwardRef } from "react"

import { recipe } from "./recipe"

const { withContext, withProvider } = createStyleContext(recipe)

export const Root = withProvider(AccordionPrimitive.Root, "root")

export const Item = withContext(AccordionPrimitive.Item, "item")

export const Header = withContext(AccordionPrimitive.Header, "header")

const ContentWrapper = withContext("div", "contentWrapper")

const ContentPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Content>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ children, ...props }, ref) => {
  return (
    <AccordionPrimitive.Content ref={ref} {...props}>
      <ContentWrapper>{children}</ContentWrapper>
    </AccordionPrimitive.Content>
  )
})

export const Content = withContext(ContentPrimitive, "content")

const TriggerPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ children, ...props }, ref) => {
  return (
    <Header>
      <AccordionPrimitive.Trigger ref={ref} {...props}>
        {children}
        <ChevronDown />
      </AccordionPrimitive.Trigger>
    </Header>
  )
})

export const Trigger = withContext(TriggerPrimitive, "trigger")

import { type RecipeVariantProps, sva } from "@styled-system/css"

export const recipe = sva({
  slots: ["root", "item", "header", "trigger", "content", "contentWrapper"],
  base: {
    root: {},
    item: {},
    header: {
      display: "flex",
    },
    trigger: {
      alignItems: "center",
      color: "foreground.emphasized",
      cursor: "pointer",
      display: "flex",
      flex: "1",
      justifyContent: "space-between",
      px: "1",
      py: "2",
      textStyle: "heading2",
      transition: "colors",

      "& > svg": {
        flexShrink: "0",
        h: "4",
        transition: "transform",
        transitionDuration: "normal",
        w: "4",
      },

      "&[data-state=open] > svg": {
        transform: "rotate(180deg)",
      },
    },
    content: {
      color: "foreground.muted",
      overflow: "hidden",
      textStyle: "body2",
      transition: "all",

      "&[data-state=closed]": {
        animationDuration: "normal",
        animationName: "accordion-up_radix",
      },

      "&[data-state=open]": {
        animationDuration: "normal",
        animationName: "accordion-down_radix",
      },
    },
    contentWrapper: {
      px: "1",
      py: "1",
    },
  },
  variants: {
    variant: {
      outline: {
        trigger: {
          _hover: {
            color: "primary",
          },
        },
        item: {
          borderBottom: "base",
        },
      },
      subtle: {
        item: {
          borderRadius: "md",
          "&[data-state=open]": {
            bg: "neutral",
          },
        },
        header: {
          borderRadius: "md",
        },
        trigger: {
          borderRadius: "md",
          _hover: {
            bg: "neutral",
            borderRadius: "md",
          },
        },
      },
    },
  },
  defaultVariants: {
    variant: "outline",
  },
})

export type AccordionVariants = RecipeVariantProps<typeof recipe>

import { cn } from "@utils/cn"
import { ChevronDown } from "lucide-react"
import { Accordion as AccordionPrimitive } from "radix-ui"
import {
  type ComponentPropsWithoutRef,
  createContext,
  type ElementRef,
  forwardRef,
  useContext,
} from "react"
import { type VariantProps } from "tailwind-variants"

import { accordion } from "./styles"

export type AccordionVariants = VariantProps<typeof accordion>

const AccordionVariantContext = createContext<AccordionVariants>({})

function useAccordionStyles() {
  return accordion(useContext(AccordionVariantContext))
}

export const Root = forwardRef<
  ElementRef<typeof AccordionPrimitive.Root>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Root> & AccordionVariants
>(({ className, variant, ...props }, ref) => {
  const styles = accordion({ variant })

  return (
    <AccordionVariantContext.Provider value={{ variant }}>
      <AccordionPrimitive.Root
        ref={ref}
        className={cn(styles.root(), className)}
        {...props}
      />
    </AccordionVariantContext.Provider>
  )
})

Root.displayName = AccordionPrimitive.Root.displayName

export const Item = forwardRef<
  ElementRef<typeof AccordionPrimitive.Item>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => {
  const styles = useAccordionStyles()

  return (
    <AccordionPrimitive.Item
      ref={ref}
      className={cn(styles.item(), className)}
      {...props}
    />
  )
})

Item.displayName = AccordionPrimitive.Item.displayName

export const Header = forwardRef<
  ElementRef<typeof AccordionPrimitive.Header>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Header>
>(({ className, ...props }, ref) => {
  const styles = useAccordionStyles()

  return (
    <AccordionPrimitive.Header
      ref={ref}
      className={cn(styles.header(), className)}
      {...props}
    />
  )
})

Header.displayName = AccordionPrimitive.Header.displayName

const ContentWrapper = ({
  className,
  ...props
}: ComponentPropsWithoutRef<"div">) => {
  const styles = useAccordionStyles()

  return <div className={cn(styles.contentWrapper(), className)} {...props} />
}

const ContentPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Content>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ children, className, ...props }, ref) => {
  const styles = useAccordionStyles()

  return (
    <AccordionPrimitive.Content
      ref={ref}
      className={cn(styles.content(), className)}
      {...props}
    >
      <ContentWrapper>{children}</ContentWrapper>
    </AccordionPrimitive.Content>
  )
})

ContentPrimitive.displayName = AccordionPrimitive.Content.displayName

export const Content = ContentPrimitive

const TriggerPrimitive = forwardRef<
  ElementRef<typeof AccordionPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ children, className, ...props }, ref) => {
  const styles = useAccordionStyles()

  return (
    <Header>
      <AccordionPrimitive.Trigger
        ref={ref}
        className={cn(styles.trigger(), className)}
        {...props}
      >
        {children}
        <ChevronDown />
      </AccordionPrimitive.Trigger>
    </Header>
  )
})

TriggerPrimitive.displayName = AccordionPrimitive.Trigger.displayName

export const Trigger = TriggerPrimitive

import { tv } from "tailwind-variants"

export const accordion = tv({
  slots: {
    root: "",
    item: "",
    header: "flex",
    trigger: [
      "flex flex-1 cursor-pointer items-center justify-between px-1 py-2 text-foreground-emphasized text-style-heading2 transition-colors",
      "[&>svg]:size-4 [&>svg]:shrink-0 [&>svg]:transition-transform",
      "data-[state=open]:[&>svg]:rotate-180",
    ],
    content:
      "overflow-hidden text-foreground-muted text-style-body2 transition-all data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down",
    contentWrapper: "px-1 py-1",
  },
  variants: {
    variant: {
      outline: {
        trigger: "[&:hover]:text-primary",
        item: "border-b border-stroke",
      },
      subtle: {
        item: "rounded-md data-[state=open]:bg-neutral",
        header: "rounded-md",
        trigger: "rounded-md [&:hover]:bg-neutral",
      },
    },
  },
  defaultVariants: {
    variant: "outline",
  },
})
